    if endpoint.endswith(":9991" + suffix):
        print("  [OK]   %s.ENDPOINT = %s" % (name, endpoint))
    else:
        print("  [FAIL] %s.ENDPOINT = %s (expected suffix %s)" % (name, endpoint, suffix))
