# --- LLM gating: web_extract.py and the SKILL "LLM extraction" section ship only with an LLM
echo
echo "===== LLM gating: scripts and skill section follow the LLM choice ====="
llm_scenario() {  # llm_scenario LABEL HOMEDIR TARGET EXPECT_LLM(yes|no) EXPECT_ACCOUNT(yes|no); answers on stdin
  local label="$1" h="$2" t="$3" want="$4" acct="$5"
  mkdir -p "$h"
  env HOME="$h" PATH="$MOCKBIN:$PATH" "$SRC_DIR/install-local-search.sh" > "$TESTROOT/llm-$label.log" 2>&1
  local rc=$? sd="$h/.agents/skills/local-web-search" ok=1
  [ "$rc" = 0 ] || { echo "  [FAIL] $label: installer exit code $rc"; ok=0; }
  for d in "$t/local-web-search" "$sd"; do
    if [ "$want" = yes ]; then
      [ -s "$d/scripts/web_extract.py" ] && grep -q "^## LLM extraction" "$d/SKILL.md" \
        || { echo "  [FAIL] $label: web_extract.py / LLM section missing in $d"; ok=0; }
    else
      [ ! -e "$d/scripts/web_extract.py" ] && ! grep -qi "LLM" "$d/SKILL.md" \
        || { echo "  [FAIL] $label: LLM extraction present in $d without an LLM"; ok=0; }
    fi
    [ ! -e "$d/SKILL-llm.md" ] && [ ! -e "$d/SKILL-core.md" ] \
      || { echo "  [FAIL] $label: build-time SKILL variant leaked into $d"; ok=0; }
    if [ "$acct" = yes ]; then
      [ -s "$d/scripts/web_monitor_create.py" ] || { echo "  [FAIL] $label: account tools missing in $d"; ok=0; }
    else
      [ ! -e "$d/scripts/web_monitor_create.py" ] || { echo "  [FAIL] $label: account tools present in $d"; ok=0; }
    fi
  done
  if [ "$ok" = 1 ]; then echo "  [OK]   $label"; else tail -15 "$TESTROOT/llm-$label.log"; PASS=0; fi
}
# setup 2 with explicit endpoint, key and model
llm_scenario opt2 "$TESTROOT/home-opt2" "$TESTROOT/home-opt2/local-search" yes no < <(printf '%s\n' 2 "http://localhost:8080/v1" "sk-e2e-key" "my-model" "y")
if grep -qx "OPENAI_BASE_URL=http://host.docker.internal:8080/v1" "$TESTROOT/home-opt2/local-search/.env" \
   && grep -qx "OPENAI_API_KEY=sk-e2e-key" "$TESTROOT/home-opt2/local-search/.env" \
   && grep -qx "MODEL_NAME=my-model" "$TESTROOT/home-opt2/local-search/.env"; then
  echo "  [OK]   opt2: .env holds base URL (localhost rewritten for the container), key and model"
else
  echo "  [FAIL] opt2: .env LLM settings wrong"; grep -E "OPENAI|MODEL" "$TESTROOT/home-opt2/local-search/.env"; PASS=0
fi
# Enter at the setup-type prompt selects setup 1 (minimal): no LLM anywhere
llm_scenario enter "$TESTROOT/home-enter" "$TESTROOT/home-enter/local-search" no no < <(printf '\n')
if ! grep -q "^OPENAI_" "$TESTROOT/home-enter/local-search/.env"; then
  echo "  [OK]   enter: minimal install, no LLM settings in .env"
else
  echo "  [FAIL] enter: LLM settings written without choosing an LLM"; PASS=0
fi
# setup 3, Step 5 left at its default (Enter = no): no LLM anywhere
llm_scenario opt3-nollm "$TESTROOT/home-opt3n" "$TESTROOT/target-opt3n" no no < <(printf '%s\n' 3 "$TESTROOT/target-opt3n" "" "" "n" "" "n" "y")
# setup 3, LLM answered y with default endpoint, key and model, plus a Firecrawl account: every feature installed
llm_scenario opt3-all "$TESTROOT/home-opt3y" "$TESTROOT/target-opt3y" yes yes < <(printf '%s\n' 3 "$TESTROOT/target-opt3y" "" "" "n" "y" "" "" "" "y" "fc-llm-key" "" "y")
# invalid setup type is re-asked, then 1 selects the minimal install
llm_scenario invalid "$TESTROOT/home-inv" "$TESTROOT/home-inv/local-search" no no < <(printf '%s\n' x 9 1)
grep -q "Please enter 1, 2 or 3" "$TESTROOT/llm-invalid.log" \
  && echo "  [OK]   invalid setup type re-prompts" \
  || { echo "  [FAIL] invalid setup type was not re-prompted"; PASS=0; }

# =============================================================================
#  Container-engine scenarios: Podman preferred, Docker fallback, SELinux, rootless
#  Every tool on PATH is a mock (or a symlink farm of the real system tools with
#  podman/docker/getenforce/systemctl/service/sudo removed), so the result does
#  not depend on what is installed on the machine running the tests.
# =============================================================================
echo
echo "===== container engine: Podman preferred, Docker fallback, SELinux, rootless ====="

MK="$TESTROOT/mocks"; mkdir -p "$MK"

# One generic mock used as both `podman` and `docker`. Behaviour per run via env:
#   MOCK_LOG                file that records every call ("<tool> <args>")
#   MOCK_PODMAN_UP/MOCK_DOCKER_UP=0         `info` fails (engine not running)
#   MOCK_PODMAN_NOCOMPOSE/MOCK_DOCKER_NOCOMPOSE=1   `compose version` fails
#   MOCK_ROOTLESS=true      `podman info --format {{.Host.Security.Rootless}}`
#   MOCK_COMPOSE_LOGS       what `compose logs` prints
mock_engine() {  # mock_engine DIR NAME
  mkdir -p "$1"
  cat > "$1/$2" <<'ENGMOCK'
#!/usr/bin/env bash
me="$(basename "$0")"; ME="$(printf '%s' "$me" | tr a-z A-Z)"
[ -n "${MOCK_LOG:-}" ] && printf '%s %s\n' "$me" "$*" >> "$MOCK_LOG"
upvar="MOCK_${ME}_UP"; nocomp="MOCK_${ME}_NOCOMPOSE"
case "$1" in
  info)
    [ "${!upvar:-1}" = 1 ] || exit 1
    case "${3:-}" in
      *Rootless*)     echo "${MOCK_ROOTLESS:-false}" ;;
      *RemoteSocket*) echo "true" ;;
    esac
    exit 0 ;;
  machine) exit 1 ;;
  exec)   # `<engine> exec <container> <cmd...>`: what the stack sees from the inside
    if [ "$3" = env ]; then      # container environment; the override's blanking removes MOCK_CONTAINER_ENV
      if [ "${MOCK_PROXY_STICKY:-0}" = 1 ] || ! grep -q "^# ls-proxy-vars: ." ./docker-compose.override.yml 2>/dev/null; then
        printf '%s\n' "${MOCK_CONTAINER_ENV:-PATH=/usr/bin}"
      fi
      exit 0
    fi
    exit 0 ;;
  compose)
    case "$2" in
      version) [ "${!nocomp:-0}" = 1 ] && exit 1; echo "Compose v2.0.0-test"; exit 0 ;;
      logs)    printf '%s\n' "${MOCK_COMPOSE_LOGS:-}"; exit 0 ;;
      ps)      echo "mock-ps-output"; exit 0 ;;
      *)       exit 0 ;;
    esac ;;
  *) exit 0 ;;
esac
ENGMOCK
  chmod +x "$1/$2"
}
mock_engine "$MK/podman" podman
mock_engine "$MK/docker" docker
for st in on off; do
  mkdir -p "$MK/se-$st"
  printf '#!/usr/bin/env bash\necho %s\n' "$([ $st = on ] && echo Enforcing || echo Disabled)" > "$MK/se-$st/getenforce"
  chmod +x "$MK/se-$st/getenforce"
done

# symlink farm of the real tools minus everything engine/service related
CLEAN="$MK/clean"; mkdir -p "$CLEAN"
IFS=: read -r -a _real_dirs <<< "$REAL_PATH"
for _d in "${_real_dirs[@]}"; do
  [ -d "$_d" ] || continue
  for _f in "$_d"/*; do
    _b="${_f##*/}"
    case "$_b" in podman|podman-compose|docker|docker-compose|getenforce|systemctl|service|sudo) continue ;; esac
    if [ -f "$_f" ] && [ -x "$_f" ] && [ ! -e "$CLEAN/$_b" ]; then ln -s "$_f" "$CLEAN/$_b"; fi
  done
done

ANS='1\n'   # installer answers: setup type 1 (minimal) unless a scenario overrides
run_install() {  # run_install LABEL PATH HOME [VAR=val ...]  -> RUN_RC, log in $TESTROOT/eng-LABEL.log
  local label="$1" pth="$2" h="$3"; shift 3
  mkdir -p "$h"
  printf "$ANS" | env -u LOCAL_SEARCH_ENGINE HOME="$h" PATH="$pth" "$@" \
      "$SRC_DIR/install-local-search.sh" > "$TESTROOT/eng-$label.log" 2>&1
  RUN_RC=$?
}
eng_check() {  # eng_check DESCRIPTION  (reads the exit status of the previous test)
  if [ "$?" = 0 ]; then echo "  [OK]   $1"; else echo "  [FAIL] $1"; PASS=0; fi
}
envval() { grep -E "^$2=" "$1" 2>/dev/null | tail -n 1 | cut -d= -f2-; }

P_BOTH="$MK/podman:$MK/docker:$MK/se-off:$CLEAN"

# 1. both installed and running -> Podman wins; nothing goes through docker
S1_LOG="$TESTROOT/s1.calls"; : > "$S1_LOG"
run_install s1 "$P_BOTH" "$TESTROOT/h-s1" MOCK_LOG="$S1_LOG"
S1_ENV="$TESTROOT/h-s1/local-search/.env"
[ "$RUN_RC" = 0 ] && grep -q "Podman and its compose tool" "$TESTROOT/eng-s1.log"
eng_check "both installed: installer picked Podman"
grep -q "^podman compose pull" "$S1_LOG" && grep -q "^podman compose up -d" "$S1_LOG" && ! grep -q "^docker compose" "$S1_LOG"
eng_check "both installed: pull + up ran through 'podman compose', never docker"
[ "$(envval "$S1_ENV" LOCAL_SEARCH_ENGINE)" = podman ]
eng_check "both installed: .env records LOCAL_SEARCH_ENGINE=podman"
[ -z "$(envval "$S1_ENV" SEARXNG_MOUNT_OPTS)" ] && [ "$(envval "$S1_ENV" SEARXNG_FORCE_OWNERSHIP)" = true ]
eng_check "no SELinux + rootful: SEARXNG_MOUNT_OPTS empty, SEARXNG_FORCE_OWNERSHIP=true"

# 2. SELinux + rootless Podman -> ,z label, no re-chown, readable config folder
S2_LOG="$TESTROOT/s2.calls"; : > "$S2_LOG"
run_install s2 "$MK/podman:$MK/docker:$MK/se-on:$CLEAN" "$TESTROOT/h-s2" MOCK_LOG="$S2_LOG" MOCK_ROOTLESS=true
S2_ENV="$TESTROOT/h-s2/local-search/.env"
[ "$RUN_RC" = 0 ] && [ "$(envval "$S2_ENV" SEARXNG_MOUNT_OPTS)" = ",z" ] \
  && [ "$(envval "$S2_ENV" SEARXNG_FORCE_OWNERSHIP)" = false ]
eng_check "SELinux + rootless Podman: SEARXNG_MOUNT_OPTS=,z and SEARXNG_FORCE_OWNERSHIP=false"
grep -q "SELinux detected" "$TESTROOT/eng-s2.log" && grep -q "Rootless Podman detected" "$TESTROOT/eng-s2.log"
eng_check "SELinux + rootless Podman: the installer says so"
[ "$(stat -c %a "$TESTROOT/h-s2/local-search/config/searxng" 2>/dev/null || stat -f %Lp "$TESTROOT/h-s2/local-search/config/searxng")" = 755 ] \
  && [ "$(stat -c %a "$TESTROOT/h-s2/local-search/config/searxng/settings.yml" 2>/dev/null || stat -f %Lp "$TESTROOT/h-s2/local-search/config/searxng/settings.yml")" = 644 ]
eng_check "config/searxng is 755 and settings.yml 644 (readable by the container user)"

# 2b. SELinux + Docker (rootful): label yes, ownership switch stays true
run_install s2b "$MK/docker:$MK/se-on:$CLEAN" "$TESTROOT/h-s2b"
S2B_ENV="$TESTROOT/h-s2b/local-search/.env"
[ "$RUN_RC" = 0 ] && [ "$(envval "$S2B_ENV" LOCAL_SEARCH_ENGINE)" = docker ] \
  && [ "$(envval "$S2B_ENV" SEARXNG_MOUNT_OPTS)" = ",z" ] && [ "$(envval "$S2B_ENV" SEARXNG_FORCE_OWNERSHIP)" = true ]
eng_check "SELinux + Docker: ,z label, ownership untouched (true), engine=docker"

# 3. Podman not installed -> Docker
S3_LOG="$TESTROOT/s3.calls"; : > "$S3_LOG"
run_install s3 "$MK/docker:$MK/se-off:$CLEAN" "$TESTROOT/h-s3" MOCK_LOG="$S3_LOG"
[ "$RUN_RC" = 0 ] && grep -q "^docker compose up -d" "$S3_LOG" && grep -q "Docker and its compose tool" "$TESTROOT/eng-s3.log" \
  && [ "$(envval "$TESTROOT/h-s3/local-search/.env" LOCAL_SEARCH_ENGINE)" = docker ]
eng_check "only Docker installed: installer uses Docker"

# 4. nothing installed -> clean error with install help
run_install s4 "$MK/se-off:$CLEAN" "$TESTROOT/h-s4"
[ "$RUN_RC" != 0 ] && grep -q "Neither Podman nor Docker was found" "$TESTROOT/eng-s4.log" && grep -q "dnf install podman" "$TESTROOT/eng-s4.log"
eng_check "no engine installed: clean error + install instructions, exit 1"

# 5. explicit overrides
S5_LOG="$TESTROOT/s5.calls"; : > "$S5_LOG"
run_install s5 "$P_BOTH" "$TESTROOT/h-s5" MOCK_LOG="$S5_LOG" LOCAL_SEARCH_ENGINE=docker
[ "$RUN_RC" = 0 ] && grep -q "^docker compose up -d" "$S5_LOG" && ! grep -q "^podman compose" "$S5_LOG" \
  && [ "$(envval "$TESTROOT/h-s5/local-search/.env" LOCAL_SEARCH_ENGINE)" = docker ]
eng_check "LOCAL_SEARCH_ENGINE=docker beats the Podman preference"
run_install s5b "$MK/docker:$MK/se-off:$CLEAN" "$TESTROOT/h-s5b" LOCAL_SEARCH_ENGINE=podman
[ "$RUN_RC" != 0 ] && grep -q "'podman' was not found on your PATH" "$TESTROOT/eng-s5b.log"
eng_check "LOCAL_SEARCH_ENGINE=podman without Podman installed: explicit error (no silent switch)"
run_install s5c "$P_BOTH" "$TESTROOT/h-s5c" LOCAL_SEARCH_ENGINE=lxc
[ "$RUN_RC" != 0 ] && grep -q "must be 'podman' or 'docker'" "$TESTROOT/eng-s5c.log"
eng_check "invalid LOCAL_SEARCH_ENGINE value is rejected"

# 6. Podman installed but unusable
run_install s6 "$P_BOTH" "$TESTROOT/h-s6" MOCK_PODMAN_UP=0
[ "$RUN_RC" = 0 ] && grep -q "using Docker instead" "$TESTROOT/eng-s6.log" \
  && [ "$(envval "$TESTROOT/h-s6/local-search/.env" LOCAL_SEARCH_ENGINE)" = docker ]
eng_check "auto-picked Podman not responding + Docker running: falls back to Docker (announced)"
run_install s6b "$P_BOTH" "$TESTROOT/h-s6b" MOCK_PODMAN_UP=0 LOCAL_SEARCH_ENGINE=podman
[ "$RUN_RC" != 0 ] && grep -q "Could not start the Podman engine automatically" "$TESTROOT/eng-s6b.log" && grep -q "podman info" "$TESTROOT/eng-s6b.log"
eng_check "forced Podman not responding: no fallback, clean error with 'podman info' hint"
run_install s6c "$P_BOTH" "$TESTROOT/h-s6c" MOCK_PODMAN_UP=0 MOCK_DOCKER_UP=0
[ "$RUN_RC" != 0 ] && grep -q "Could not start the Podman engine automatically" "$TESTROOT/eng-s6c.log"
eng_check "Podman and Docker both down: clean error"

# 7. Podman without any compose provider
run_install s7 "$P_BOTH" "$TESTROOT/h-s7" MOCK_PODMAN_NOCOMPOSE=1
[ "$RUN_RC" != 0 ] && grep -q "No compose provider was found for Podman" "$TESTROOT/eng-s7.log" && grep -q "dnf install docker-compose" "$TESTROOT/eng-s7.log"
eng_check "Podman without a compose provider: clear error naming the package to install"

# 8. run/stop/update follow the engine recorded in .env
S8_DIR="$TESTROOT/h-s1/local-search"; S8_LOG="$TESTROOT/s8.calls"; : > "$S8_LOG"
S8_RUN() { env -u LOCAL_SEARCH_ENGINE HOME="$TESTROOT/h-s1" PATH="$P_BOTH" MOCK_LOG="$S8_LOG" "$@"; }
S8_RUN "$S8_DIR/run.sh" > "$TESTROOT/s8-run.log" 2>&1; S8RC=$?
S8_RUN "$S8_DIR/stop.sh" > "$TESTROOT/s8-stop.log" 2>&1
S8_RUN "$S8_DIR/update.sh" > "$TESTROOT/s8-update.log" 2>&1
[ "$S8RC" = 0 ] && grep -q "^podman compose up -d" "$S8_LOG" && grep -q "^podman compose down" "$S8_LOG" \
  && grep -q "^podman compose pull" "$S8_LOG" && ! grep -q "^docker compose" "$S8_LOG" \
  && grep -q "with Podman" "$TESTROOT/s8-run.log"
eng_check "run.sh / stop.sh / update.sh use Podman (engine recorded in .env)"
sed -i.bak 's/^LOCAL_SEARCH_ENGINE=.*/LOCAL_SEARCH_ENGINE=docker/' "$S8_DIR/.env" && rm -f "$S8_DIR/.env.bak"
: > "$S8_LOG"; S8_RUN "$S8_DIR/run.sh" > "$TESTROOT/s8-run2.log" 2>&1
grep -q "^docker compose up -d" "$S8_LOG" && ! grep -q "^podman compose" "$S8_LOG"
eng_check "editing LOCAL_SEARCH_ENGINE=docker in .env switches run.sh to Docker"
sed -i.bak 's/^LOCAL_SEARCH_ENGINE=.*/LOCAL_SEARCH_ENGINE=podman/' "$S8_DIR/.env" && rm -f "$S8_DIR/.env.bak"
: > "$S8_LOG"
env -u LOCAL_SEARCH_ENGINE HOME="$TESTROOT/h-s1" PATH="$MK/docker:$MK/se-off:$CLEAN" MOCK_LOG="$S8_LOG" "$S8_DIR/run.sh" > "$TESTROOT/s8-run3.log" 2>&1
grep -q "^docker compose up -d" "$S8_LOG" && grep -q "not installed - auto-detecting" "$TESTROOT/s8-run3.log"
eng_check ".env names Podman but it is gone: run.sh auto-detects Docker and says so"
env -u LOCAL_SEARCH_ENGINE HOME="$TESTROOT/h-s1" PATH="$P_BOTH" MOCK_LOG="$S8_LOG" MOCK_PODMAN_UP=0 "$S8_DIR/run.sh" > "$TESTROOT/s8-run4.log" 2>&1
[ "$?" != 0 ] && grep -q "Podman engine is not running" "$TESTROOT/s8-run4.log"
eng_check "run.sh with the recorded engine down: clean error (no silent switch)"

# 9. the post-start SearXNG check
printf '%s\n' "import http.server,socketserver,sys
class H(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        self.send_response(200); self.send_header('Content-Type','text/html'); self.end_headers(); self.wfile.write(b'ok')
    def log_message(self,*a): pass
socketserver.TCPServer.allow_reuse_address=True
http.server.HTTPServer(('127.0.0.1',59980),H).serve_forever()" > "$TESTROOT/fake_searx.py"
"$PY" "$TESTROOT/fake_searx.py" >/dev/null 2>&1 & FAKE_SEARX_PID=$!
sleep 1
ANS="$(printf '3\n%s\n59980\n59981\nn\nn\nn\ny\n' "$TESTROOT/target-v1")"
run_install s9 "$P_BOTH" "$TESTROOT/h-s9" LOCAL_SEARCH_VERIFY_TIMEOUT=9
[ "$RUN_RC" = 0 ] && grep -q "SearXNG is answering on port 59980" "$TESTROOT/eng-s9.log" && grep -q "Installation complete" "$TESTROOT/eng-s9.log"
eng_check "post-start check: SearXNG answering -> 'Installation complete!'"
kill "$FAKE_SEARX_PID" 2>/dev/null; wait "$FAKE_SEARX_PID" 2>/dev/null
sleep 1
ANS="$(printf '3\n%s\n59980\n59981\nn\nn\nn\ny\n' "$TESTROOT/target-v2")"
run_install s9b "$P_BOTH" "$TESTROOT/h-s9b" LOCAL_SEARCH_VERIFY_TIMEOUT=3 \
    MOCK_COMPOSE_LOGS="chown: /etc/searxng: Permission denied"
[ "$RUN_RC" != 0 ] && grep -q "SearXNG did not answer on port 59980" "$TESTROOT/eng-s9b.log" \
  && grep -q "mock-ps-output" "$TESTROOT/eng-s9b.log" \
  && grep -q "chown: /etc/searxng: Permission denied" "$TESTROOT/eng-s9b.log" \
  && grep -q "SEARXNG_MOUNT_OPTS=,z" "$TESTROOT/eng-s9b.log" \
  && grep -q "Installed, but SearXNG is not answering" "$TESTROOT/eng-s9b.log" \
  && ! grep -q "Installation complete" "$TESTROOT/eng-s9b.log"
eng_check "post-start check: SearXNG never answers -> state + logs + SELinux hint, exit 1, no 'complete'"
ANS='1\n'

# 9c. a loopback proxy inherited from the host shell (Podman copies it into every container)
echo
echo "  -- inherited proxy variables --"
"$PY" "$TESTROOT/fake_searx.py" >/dev/null 2>&1 & FAKE_SEARX_PID=$!
sleep 1
NETENV="LOCAL_SEARCH_VERIFY_TIMEOUT=9"
net_install() {  # net_install LABEL [VAR=val ...]  (setup 3, ports 59980/59981, target-LABEL)
  local label="$1"; shift
  ANS="$(printf '3\n%s\n59980\n59981\nn\nn\nn\ny\n' "$TESTROOT/target-$label")"
  run_install "$label" "$P_BOTH" "$TESTROOT/h-$label" $NETENV "$@"
}
ovr() { echo "$TESTROOT/target-$1/docker-compose.override.yml"; }
blanked() { local f="$1" v; shift; for v in "$@"; do grep -qxF "      - \"$v=\"" "$f" || return 1; done; }
FOREIGN='services:
  searxng:
    mem_limit: 1g
'

net_install n1
[ "$RUN_RC" = 0 ] && grep -q "The containers' proxy settings are fine" "$TESTROOT/eng-n1.log" && [ ! -e "$(ovr n1)" ] && grep -q "Installation complete" "$TESTROOT/eng-n1.log"
eng_check "no inherited proxy: nothing to repair, no override file, install completes"

# --- inherited proxy variables (Podman copies the host shell's into every container) ---
LOOP_ENV="$(printf 'PATH=/usr/bin\nhttp_proxy=http://127.0.0.1:7890\nHTTPS_PROXY=http://127.0.0.1:7890\nno_proxy=localhost\n')"
net_install p1 MOCK_CONTAINER_ENV="$LOOP_ENV"
[ "$RUN_RC" = 0 ] && grep -q "inherited a proxy setting" "$TESTROOT/eng-p1.log" && grep -q "inherited loopback proxy is gone" "$TESTROOT/eng-p1.log" \
  && grep -q "^# ls-proxy-vars: http_proxy https_proxy$" "$(ovr p1)" \
  && blanked "$(ovr p1)" http_proxy HTTP_PROXY https_proxy HTTPS_PROXY \
  && [ "$(grep -c '^      - "http_proxy="' "$(ovr p1)")" = 4 ] && ! grep -qi "no_proxy" "$(ovr p1)" \
  && grep -q "Installation complete" "$TESTROOT/eng-p1.log"
eng_check "loopback proxy inherited (http://127.0.0.1:7890): found inside the container and blanked in both cases, once per service; no_proxy untouched"

CORP_ENV="$(printf 'http_proxy=http://user:pw@proxy.corp.example:3128\nHTTPS_PROXY=http://10.20.30.40:8080\n')"
net_install p2 MOCK_CONTAINER_ENV="$CORP_ENV"
[ "$RUN_RC" = 0 ] && ! grep -q "inherited a proxy setting" "$TESTROOT/eng-p2.log" && [ ! -e "$(ovr p2)" ]
eng_check "a proxy that points at a real host (corporate / LAN) is left alone - no override"

V6_ENV="$(printf 'all_proxy=socks5://localhost:1080\nftp_proxy=http://[::1]:8080/\n')"
net_install p3 MOCK_CONTAINER_ENV="$V6_ENV"
[ "$RUN_RC" = 0 ] && grep -q "^# ls-proxy-vars: all_proxy ftp_proxy$" "$(ovr p3)" && grep -qxF '      - "ALL_PROXY="' "$(ovr p3)" && grep -qxF '      - "FTP_PROXY="' "$(ovr p3)"
eng_check "socks5://localhost and http://[::1] are recognised as loopback too"

net_install p5 MOCK_CONTAINER_ENV="$LOOP_ENV" MOCK_PROXY_STICKY=1
[ "$RUN_RC" != 0 ] && grep -q "still carry a loopback proxy" "$TESTROOT/eng-p5.log" && grep -q "unset http_proxy" "$TESTROOT/eng-p5.log" \
  && grep -q "Installed, but the containers inherit a proxy setting that cannot work" "$TESTROOT/eng-p5.log"
eng_check "a proxy that cannot be removed: clear failure with the exact 'unset' command, exit 1"

mkdir -p "$TESTROOT/target-p6"; printf '%s' "$FOREIGN" > "$TESTROOT/target-p6/docker-compose.override.yml"; cp "$TESTROOT/target-p6/docker-compose.override.yml" "$TESTROOT/p6.orig"
net_install p6 MOCK_CONTAINER_ENV="$LOOP_ENV"
[ "$RUN_RC" != 0 ] && cmp -s "$TESTROOT/p6.orig" "$(ovr p6)" && grep -q "is not ours" "$TESTROOT/eng-p6.log" && grep -q "http_proxy= *https_proxy= *all_proxy=" "$TESTROOT/eng-p6.log"
eng_check "proxy problem + a user-owned override: file untouched, exact manual instructions printed"

# an override written by the previous release and hand-edited by an agent: recognised, nothing rewritten
mkdir -p "$TESTROOT/target-p7"
cat > "$TESTROOT/target-p7/docker-compose.override.yml" <<'LEGACY'
# local-search: generated container-network workaround (safe to delete - the installer rewrites it)
# ls-dns: 
# ls-proxy-vars: ftp_proxy FTP_PROXY http_proxy HTTP_PROXY https_proxy HTTPS_PROXY
services:
  firecrawl:
    environment:
      - "ALLOW_LOCAL_WEBHOOKS=true"
      - "ftp_proxy="
      - "FTP_PROXY="
      - "http_proxy="
      - "HTTP_PROXY="
      - "https_proxy="
      - "HTTPS_PROXY="
LEGACY
cp "$TESTROOT/target-p7/docker-compose.override.yml" "$TESTROOT/p7.orig"
net_install p7
