# ---- compose-config checks: ask whichever REAL compose tool is installed ---------------------
# Podman first (the product prefers it too): `podman compose` / `podman-compose`, then
# `docker compose` / `docker-compose`. Both families describe the same facts in different shapes
# (Docker: JSON + long-syntax volumes; podman-compose: YAML + `...:rw,z` strings), so the output is
# normalised before anything is asserted. Skips only when NO usable tool exists, and says why.
cat > "$TESTROOT/compose_cfg.py" <<'CFGPY'
#!/usr/bin/env python3
"""Print the merged compose config of the current directory as normalised JSON.
Exit 3 (reasons on stderr) when no installed compose tool can be used."""
import json, os, re, shutil, subprocess, sys
try:
    import yaml
except ImportError:
    yaml = None

def run(cmd):
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=90,
                           env=dict(os.environ, PODMAN_COMPOSE_WARNING_LOGS="false"))
        return p.returncode, p.stdout
    except (OSError, subprocess.SubprocessError):
        return 127, ""

text = open("docker-compose.yml", encoding="utf-8").read()
pflags = [f for p in sorted(set(re.findall(r'profiles:\s*\[\s*"([^"]+)"', text))) for f in ("--profile", p)]
cands = []
if shutil.which("podman") and run(["podman", "compose", "version"])[0] == 0:
    cands.append(("podman compose", ["podman", "compose"]))
if shutil.which("podman-compose"):
    cands.append(("podman-compose", ["podman-compose"]))
if shutil.which("docker") and run(["docker", "compose", "version"])[0] == 0:
    cands.append(("docker compose", ["docker", "compose"]))
if shutil.which("docker-compose"):
    cands.append(("docker-compose", ["docker-compose"]))

def normalise(services):
    out = {}
    for name, svc in services.items():
        env = svc.get("environment") or {}
        if isinstance(env, list):
            env = dict((e.split("=", 1) + [""])[:2] for e in env)
        env = {k: ("" if v is None else str(v)) for k, v in env.items()}
        vols = []
        for v in svc.get("volumes") or []:
            if isinstance(v, dict):                       # Docker: long syntax
                vols.append({"target": v.get("target"), "selinux": (v.get("bind") or {}).get("selinux")})
            else:                                         # podman-compose: "src:dst:rw,z"
                parts = str(v).split(":")
                opts = parts[2].split(",") if len(parts) > 2 else []
                vols.append({"target": parts[1] if len(parts) > 1 else parts[0],
                             "selinux": next((o for o in opts if o in ("z", "Z")), None)})
        dep = svc.get("depends_on") or []
        out[name] = {"environment": env, "volumes": vols, "depends_on": list(dep),
                     "profiles": list(svc.get("profiles") or [])}
    return out

reasons = []
for label, cmd in cands:
    data = None
    rc, out = run(cmd + pflags + ["config", "--format", "json"])
    if rc == 0:
        try:
            data = json.loads(out)
        except ValueError:
            data = None
    if data is None:
        rc, out = run(cmd + pflags + ["config"])
        if rc != 0:
            reasons.append("%s: 'config' failed" % label); continue
        if yaml is None:
            reasons.append("%s: prints YAML and PyYAML is not installed" % label); continue
        try:
            data = yaml.safe_load(out)
        except yaml.YAMLError:
            reasons.append("%s: unreadable output" % label); continue
    if isinstance(data, dict) and data.get("services"):
        print(json.dumps({"provider": label, "services": normalise(data["services"])}))
        sys.exit(0)
    reasons.append("%s: no services in the output" % label)
print("no usable compose tool (podman compose / podman-compose / docker compose / docker-compose): "
      + ("; ".join(reasons) or "none installed"), file=sys.stderr)
sys.exit(3)
CFGPY
cat > "$TESTROOT/compose_check.py" <<'CHKPY'
#!/usr/bin/env python3
"""compose_check.py CHECK < normalised-config.json   (exit 0 = the check holds)"""
import json, sys
cfg = json.load(sys.stdin)["services"]
sx = cfg["searxng"]
z = [v["selinux"] for v in sx["volumes"] if v["target"] == "/etc/searxng"]
force = sx["environment"].get("FORCE_OWNERSHIP")
check = sys.argv[1]
if check == "z-label":            # SEARXNG_MOUNT_OPTS=,z + SEARXNG_FORCE_OWNERSHIP=false in .env
    ok = z == ["z"] and force == "false"
elif check == "no-label":         # SEARXNG_MOUNT_OPTS= (empty) + FORCE_OWNERSHIP=false
    ok = z == [None] and force == "false"
elif check == "defaults":         # neither variable in .env (what a Windows / .bat install has)
    ok = z == [None] and force == "true"
elif check == "no-gated-deps":    # podman-compose crashes on depends_on of a profile-gated service
    gated = {n for n, s in cfg.items() if s["profiles"]}
    bad = sorted((n, d) for n, s in cfg.items() for d in s["depends_on"] if d in gated)
    print("profile-gated services:", sorted(gated), "| offending depends_on:", bad)
    ok = bool(gated) and not bad
elif check == "override-merge":    # proxies blanked on 4 services; ALLOW_LOCAL_WEBHOOKS only on the 2 scrapers
    blank = ("http_proxy", "HTTP_PROXY", "https_proxy", "HTTPS_PROXY")
    ok = True
    for n in ("searxng", "firecrawl", "playwright-service", "browserless"):
        env = cfg[n]["environment"]
        ok = ok and all(env.get(k) == "" for k in blank)
        ok = ok and (env.get("ALLOW_LOCAL_WEBHOOKS") == "true") == (n in ("firecrawl", "playwright-service"))
else:
    ok = False
if not ok:
    print("check %s failed: searxng volumes=%s FORCE_OWNERSHIP=%r" % (check, sx["volumes"], force), file=sys.stderr)
sys.exit(0 if ok else 1)
CHKPY
CFG_CACHE=""
cfg_test() {  # cfg_test CHECK DIR "what it proves"   (DIR holds docker-compose.yml + .env [+ override])
  local check="$1" dir="$2" what="$3" json prov
  if ! json="$(cd "$dir" && PATH="$REAL_PATH" "$PY" "$TESTROOT/compose_cfg.py" 2>"$TESTROOT/compose_cfg.err")"; then
    echo "  [SKIP] $what - $(tail -n 1 "$TESTROOT/compose_cfg.err")"; return 0
  fi
  prov="$(printf '%s' "$json" | "$PY" -c 'import json,sys; print(json.load(sys.stdin)["provider"])')"
  if printf '%s' "$json" | "$PY" "$TESTROOT/compose_check.py" "$check"; then
    echo "  [OK]   $what (via $prov)"
  else
    echo "  [FAIL] $what (via $prov)"; PASS=0
  fi
}

