cat > "$TESTROOT/run_pty.py" <<'PTYPY'
import os, pty, sys, time, select
def run(argv, env_extra=None, send_after=None, stdin_cmds=None, timeout=8):
    env=dict(os.environ); env.pop("LOCAL_SEARCH_PAUSE",None); env.update(env_extra or {})
    pid, fd = pty.fork()
    if pid == 0:
        os.execvpe(argv[0], argv, env)
    out=b""; t0=time.time(); sent=False; cmds=False
    while time.time()-t0 < timeout:
        r,_,_=select.select([fd],[],[],0.3)
        if r:
            try: d=os.read(fd,4096)
            except OSError: break
            if not d: break
            out+=d
        if stdin_cmds and not cmds and time.time()-t0>0.8:
            os.write(fd, stdin_cmds.encode()); cmds=True
        if send_after and not sent and send_after.encode() in out:
            os.write(fd,b"\n"); sent=True
    rc=None
    for _ in range(10):
        try: p,st=os.waitpid(pid,os.WNOHANG)
        except ChildProcessError: break
        if p: rc=os.waitstatus_to_exitcode(st); break
        time.sleep(0.3)
    if rc is None:
        try: os.kill(pid,9)
        except OSError: pass
    return out.decode(errors="replace"), rc, sent
tiny=sys.argv[1]; good=True
def case(name, ok, detail=""):
    global good
    print(("  [OK]   " if ok else "  [FAIL] ")+name+((" -> "+detail) if (detail and not ok) else ""))
    good = good and ok
o,rc,sent=run(["bash",tiny],send_after="Press any key to close")
case("launcher-style start: waits for a key, then exits with the script's own code", "Press any key to close" in o and sent and rc==3, repr((o[-100:],rc)))
o,rc,_=run(["bash","--norc","--noprofile","-i"],stdin_cmds="bash %s; echo RC=$?; exit\n"%tiny)
case("started from an interactive shell: no pause", "tiny-done" in o and "RC=3" in o and "Press any key" not in o, repr(o[-160:]))
o,rc,_=run(["bash",tiny],{"LOCAL_SEARCH_PAUSE":"0"})
case("LOCAL_SEARCH_PAUSE=0 never pauses", "tiny-done" in o and "Press any key" not in o and rc==3, repr((o[-80:],rc)))
o,rc,sent=run(["bash","--norc","--noprofile","-i"],{"LOCAL_SEARCH_PAUSE":"1"},send_after="Press any key",stdin_cmds="bash %s; echo RC=$?; exit\n"%tiny)
case("LOCAL_SEARCH_PAUSE=1 pauses even from a shell", "Press any key" in o and "RC=3" in o, repr(o[-160:]))
o,rc,sent=run(["sh","-c","bash %s; true"%tiny],send_after="Press any key to close")
case("a launcher's `sh -c` wrapper is looked through: still pauses", "Press any key to close" in o and sent, repr(o[-100:]))
o,rc,_=run(["bash","--norc","--noprofile","-i"],stdin_cmds="sh -c 'bash %s; true'; echo BACK; exit\n"%tiny)
case("`sh -c` typed in an interactive shell: no pause", "tiny-done" in o and "BACK" in o and "Press any key" not in o, repr(o[-160:]))
sys.exit(0 if good else 1)
PTYPY
