#!/usr/bin/env python3
import os, sys, json
a = sys.argv[1:]
if os.environ.get("FAKE_LOG"): open(os.environ["FAKE_LOG"], "a").write(" ".join(a) + "\n")
mode = os.environ.get("FAKE_MODE", "ok")
if "--list-subs" in a:
    print("[info] Available subtitles for X:\nLanguage Name       Formats\nde       German     json3, vtt\nfr       French     json3, vtt"); sys.exit(0)
if "--js-runtimes" in a and mode == "oldytdlp":
    sys.stderr.write("yt-dlp: error: no such option: --js-runtimes\n"); sys.exit(2)
if mode == "botcheck":
    sys.stderr.write("ERROR: [youtube] abc: Sign in to confirm you're not a bot.\n"); sys.exit(1)
if mode == "nosubs":
    print("[info] There are no subtitles for the requested languages"); sys.exit(0)
if mode == "jsfail":
    sys.stderr.write("WARNING: n challenge solving failed\nERROR: Requested format is not available\n"); sys.exit(1)
tmpl = a[a.index("-o") + 1]; vid = a[-1].split("v=")[-1]
langs = a[a.index("--sub-langs") + 1].split(",")
code = "en-orig" if mode == "orig" else ("de" if any(l.startswith("de") for l in langs) else "en")
if mode == "orig":
    open(tmpl.replace("%(id)s", vid).replace("%(ext)s", "fr.json3"), "w").write(json.dumps({"events": [{"tStartMs": 0, "segs": [{"utf8": "NOT THIS"}]}]}))
ev = [{"tStartMs": 0, "wWinId": 1}, {"tStartMs": 1500, "segs": [{"utf8": "Hello"}, {"utf8": " world"}]},
      {"tStartMs": 4200, "segs": [{"utf8": "\n"}]}, {"tStartMs": 65000, "segs": [{"utf8": "second\nline"}]},
      {"tStartMs": 4500000, "segs": [{"utf8": "after one hour"}]}]
json.dump({"events": ev}, open(tmpl.replace("%(id)s", vid).replace("%(ext)s", code + ".json3"), "w"))
FAKEYT
