# 10. the compose file itself (parsed by the REAL compose tool: Podman first, then Docker)
echo
echo "  -- docker-compose.yml checks --"
CF="$TGT_DIR/docker-compose.yml"
if [ "$(grep -c 'ALLOW_LOCAL_WEBHOOKS=true' "$CF")" = 2 ] && ! grep -q 'ALLOW_LOCAL_WEBHOOKS=false' "$CF" \
   && awk '/^  [a-z-]+:$/ {svc=$1} /ALLOW_LOCAL_WEBHOOKS=true/ {print svc}' "$CF" | tr -d ':' | tr '\n' ' ' | grep -qx 'firecrawl playwright-service '; then
  echo "  [OK]   docker-compose.yml: ALLOW_LOCAL_WEBHOOKS=true is built in for firecrawl and playwright-service (unconditional - proxy/VPN fake-IP DNS can never block scraping)"
else
  echo "  [FAIL] docker-compose.yml must set ALLOW_LOCAL_WEBHOOKS=true for firecrawl and playwright-service, and nowhere else"; PASS=0
fi
if grep -E '^\s+image:' "$CF" | grep -vqE 'image:\s+(docker\.io|ghcr\.io)/'; then
  echo "  [FAIL] an image in docker-compose.yml is not fully qualified (docker.io/ or ghcr.io/)"; PASS=0
else
  echo "  [OK]   every image is fully qualified (docker.io/ or ghcr.io/ only) - Podman never prompts for a registry"
fi
